using Asp.Versioning;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Servicio.RetazoMarket.Api.Extensions;using Servicio.RetazoMarket.Api.Models.Common;using Servicio.RetazoMarket.Business.DTOs.MovimientoMaterial;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Api.Controllers.V1.Internal.Inventario;
[ApiController][ApiVersion("1.0")][Authorize(Policy=AuthorizationExtensions.AdministradorPolicy)][Route("api/v{version:apiVersion}/internal/inventario/movimientos-materiales")][ProducesResponseType(typeof(ApiErrorResponse),400)][ProducesResponseType(typeof(ApiErrorResponse),401)][ProducesResponseType(typeof(ApiErrorResponse),403)][ProducesResponseType(typeof(ApiErrorResponse),404)]
public class MovimientosMaterialesController:ControllerBase{private readonly IMovimientoMaterialService _s;public MovimientosMaterialesController(IMovimientoMaterialService s)=>_s=s;
[HttpGet("{id:int}")]public async Task<IActionResult> PorId(int id,CancellationToken ct)=>Ok(ApiResponse<MovimientoMaterialResponse>.Ok(await _s.ObtenerPorIdAsync(id,ct)??throw new NotFoundException("El movimiento no existe.")));
[HttpGet("material/{id:int}")]public async Task<IActionResult> PorMaterial(int id,CancellationToken ct)=>Ok(ApiResponse<IReadOnlyList<MovimientoMaterialResponse>>.Ok(await _s.ObtenerPorMaterialAsync(id,ct)));
[HttpGet("buscar")]public async Task<IActionResult> Buscar([FromQuery]MovimientoMaterialFiltroRequest f,CancellationToken ct)=>Ok(ApiResponse<DataPagedResult<MovimientoMaterialResponse>>.Ok(await _s.BuscarAsync(f,ct)));
[HttpPost]public async Task<IActionResult> Crear([FromBody]CrearMovimientoMaterialRequest r,CancellationToken ct){var x=await _s.CrearAsync(r,ct);return CreatedAtAction(nameof(PorId),new{version="1.0",id=x.id_movimiento},ApiResponse<MovimientoMaterialResponse>.Ok(x,"Movimiento registrado exitosamente."));}}
